using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading.Tasks;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using CrossTheLine;
public static class AllChapterStateRenderedAudit {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static void Call(JourneyGame g,string n,params object[] a)=>typeof(JourneyGame).GetMethod(n,F).Invoke(g,a);
 public static async Task<string> Range(int start,int end){var g=UnityEngine.Object.FindAnyObjectByType<JourneyGame>();var w=g.GetComponent<JourneyContinuousWorld>();var book=JsonUtility.FromJson<StoryBook>(g.storySource.text);bool saving=JourneySceneFlow.TestWithoutSaving;var rows=new List<string>{"chapter\tstep\tmode\tvisible\tviewport\tenabled\tactive\talpha\tsamples"};SpriteRenderer body=null;Vector3 v=Vector3.zero;int samples=0,fail=0,total=0;Action<ScriptableRenderContext,Camera> cb=(context,c)=>{if(c==g.journeyCamera&&body){v=c.WorldToViewportPoint(body.bounds.center);samples++;}};
 try{JourneySceneFlow.TestWithoutSaving=true;Time.timeScale=1;RenderPipelineManager.beginCameraRendering+=cb;Directory.CreateDirectory("Docs/QA/RenderedChapters");
 for(int i=start;i<end;i++)for(int step=0;step<book.chapters[i].steps.Length;step++){w.Normalize();Call(g,"ClearStoryPanels");typeof(JourneyGame).GetField("save",F).SetValue(g,new JourneySave{chapter=i,step=step,unlocked=26});typeof(JourneyGame).GetField("started",F).SetValue(g,true);Call(g,"CloseMenu");Call(g,"LoadWorld",false);body=g.PlayerRoot.GetComponentInChildren<SpriteRenderer>(true);samples=0;float settle=Time.realtimeSinceStartup+(step==0?1.6f:.25f);while(Time.realtimeSinceStartup<settle)await Task.Yield();bool visible=samples>0&&body.enabled&&body.gameObject.activeInHierarchy&&body.color.a>.05f&&v.x>0&&v.x<1&&v.y>0&&v.y<1&&v.z>0;total++;if(!visible){fail++;ScreenCapture.CaptureScreenshot(Path.GetFullPath("Docs/QA/RenderedChapters/Review-"+(i+1).ToString("00")+"-"+step+".png"));}rows.Add($"{i+1}\t{step}\t{g.Mode}\t{visible}\t{v}\t{body.enabled}\t{body.gameObject.activeInHierarchy}\t{body.color.a}\t{samples}");}
 File.WriteAllLines("Docs/QA/RenderedChapters/States"+start+"-"+end+".tsv",rows);return "Rendered "+total+" states; "+fail+" camera/visibility candidates:\n"+string.Join("\n",rows.Where(r=>r.Contains("False")));
 }finally{RenderPipelineManager.beginCameraRendering-=cb;JourneySceneFlow.TestWithoutSaving=saving;Time.timeScale=1;}
 }
}
